<?php require __DIR__.'/api/bootstrap.php';if(uid()){header('Location:index.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$q=db()->prepare('SELECT * FROM medicos WHERE crm=?');$q->execute([trim($_POST['crm']??'')]);$u=$q->fetch(PDO::FETCH_ASSOC);if($u&&password_verify($_POST['senha']??'',$u['senha_hash'])){session_regenerate_id(true);$_SESSION['doctor_id']=$u['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location:index.php');exit;}$err='CRM ou senha inválidos.';}?><!doctype html><html lang="pt-BR"><head><?php require __DIR__.'/partials/head.php';?></head><body><main style="max-width:440px;padding-top:10vh"><div class="panel"><h1>DrJulio</h1><p>Acesso profissional</p><?php if($err):?><p><?=e($err)?></p><?php endif?><form method="post"><label>CRM</label><input name="crm" required><label>Senha</label><input type="password" name="senha" required><button class="btn">Entrar</button></form><p><a href="install.php">Instalar</a></p></div></main></body></html>